corrected_code:
export const expenseRouter = router({
  getExpenseDetails: protectedProcedure
    .input(z.object({ expenseId: z.number().int() }))
    .query(async ({ input, ctx }) => {
      const record = await ctx.knex('expense_claims')
        .where({ id: input.expenseId, employee_id: ctx.user.employeeId })
        .first();
      if (!record) throw new TRPCError({ code: 'FORBIDDEN', message: 'Access to target expense claim denied' });
      return record;
    }),
});
